def money(value):
    return f"₹{value:,.0f}"


@st.cache_data(show_spinner="Loading Pune bus options…")
def prepare_bus_data():
    from bus_modules.data_loader import load_gtfs
    from bus_modules.route_stats import build_route_stops
    from bus_modules.journey import build_network
    from bus_modules.places import build_places, ALIASES
    from bus_modules.metro import load_metro
    data = load_gtfs(str(GTFS))
    route_stops = build_route_stops(data)
    network = build_network(data, route_stops)
    stop_names = sorted(data["stops"]["stop_name"].dropna().astype(str).unique(), key=str.casefold)
    places = sorted(set(build_places(route_stops)) | set(ALIASES) | set(stop_names), key=str.casefold)
    metro = load_metro(str(GTFS / "metro_stations.csv"))
    return data, route_stops, network, places, metro


@st.cache_data(ttl=3600, show_spinner=False)
def safe_road_distance(source_coords, destination_coords):
    """Road distance for any catalogue location, with a coordinate fallback."""
    try:
        return get_road_distance_between(source_coords, destination_coords), "Road-distance estimate"
    except Exception:
        lat1, lon1, lat2, lon2 = map(
            math.radians,
            [source_coords[0], source_coords[1], destination_coords[0], destination_coords[1]],
        )
        h = math.sin((lat2-lat1)/2)**2 + math.cos(lat1)*math.cos(lat2)*math.sin((lon2-lon1)/2)**2
        straight = 6371 * 2 * math.asin(math.sqrt(h))
        return round(straight * 1.28, 1), "Approximate distance (routing service unavailable)"


def load_expenses():
    if not EXPENSE_FILE.exists():
        return pd.DataFrame(columns=["date", "route", "mode", "amount", "note"])
    try:
        df = pd.read_csv(EXPENSE_FILE)
        df["date"] = pd.to_datetime(df["date"], errors="coerce").dt.date
        df["amount"] = pd.to_numeric(df["amount"], errors="coerce").fillna(0)
        return df.dropna(subset=["date"])
    except Exception:
        return pd.DataFrame(columns=["date", "route", "mode", "amount", "note"])


def save_expense(date, route, mode, amount, note):
    EXPENSE_FILE.parent.mkdir(parents=True, exist_ok=True)
    row = pd.DataFrame([{"date": date, "route": route, "mode": mode, "amount": amount, "note": note}])
    row.to_csv(EXPENSE_FILE, mode="a", header=not EXPENSE_FILE.exists(), index=False)


def delete_expense(row_index):
    """Delete one saved expense by its original CSV row index."""
    expenses = load_expenses()
    if row_index not in expenses.index:
        return False
    expenses = expenses.drop(index=row_index).reset_index(drop=True)
    EXPENSE_FILE.parent.mkdir(parents=True, exist_ok=True)
    expenses.to_csv(EXPENSE_FILE, index=False)
    return True


def clean_key(value):
    return re.sub(r"[^a-z0-9]+", "", str(value).lower())


